 // is valid in git or if it is malformed.
 func FromBytes(b []byte) (FileMode, error) {
-	if len(b) == 0 || len(b) > 7 {
+	if len(b) == 0 {
 		return Empty, fmt.Errorf("invalid mode length: %d", len(b))
 	}

@@ -80,6 +81,9 @@ func FromBytes(b []byte) (FileMode, error) {
 		if c < '0' || c > '7' {
 			return Empty, fmt.Errorf("invalid octal character: %c", c)
 		}
+		if mode > (^uint32(0)-uint32(c-'0'))/8 {
+			return Empty, fmt.Errorf("mode overflows uint32")
+		}
 		mode = mode*8 + uint32(c-'0')
 	}
 	return FileMode(mode), nil
@@ -142,6 +146,26 @@ func (m FileMode) Bytes() []byte {
 	return ret
 }

+// Canonical returns the mode Git uses when reading a tree entry.
+// Regular files use only the owner execute bit to select Executable or
+// Regular. Directories and symlinks retain their type with permission bits
+// removed; all other types map to Submodule. This does not validate m.
+func (m FileMode) Canonical() FileMode {
+	switch m & 0o170000 {
+	case 0o040000:
+		return Dir
+	case 0o100000:
+		if m&0o100 != 0 {
+			return Executable
+		}
+		return Regular
+	case 0o120000:
+		return Symlink
+	default:
+		return Submodule
+	}
+}
+
 // IsMalformed returns if the FileMode should not appear in a git packfile,
 // this is: Empty and any other mode not mentioned as a constant in this
 // package.
