+func (s *ModeSuite) TestCanonical() {
+	for _, test := range []struct {
+		mode FileMode
+		want FileMode
+	}{
+		{Regular, Regular},
+		{Deprecated, Regular},
+		{Executable, Executable},
+		{Dir, Dir},
+		{Symlink, Symlink},
+		{Submodule, Submodule},
+		{0o100000, Regular},
+		{0o100654, Regular},
+		{0o100645, Regular},
+		{0o100744, Executable},
+		{0o104100, Executable},
+		{0o040755, Dir},
+		{0o120777, Symlink},
+		{0o160755, Submodule},
